<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick,watch} from 'vue'
import {request,setToken,selectGroup} from './api'
import AccountShortcuts from './components/AccountShortcuts.vue'
import NodePanel from './components/NodePanel.vue'
import NotificationPanel from './components/NotificationPanel.vue'
import MailJobsPanel from './components/MailJobsPanel.vue'
import PublicAccessPanel from './components/PublicAccessPanel.vue'
const mailPanel=ref(null),unreadCount=ref(0)
const user=ref(null),group=ref(null),members=ref([]),discussions=ref([]),tab=ref('groups'),joined=ref(false),error=ref(''),busy=ref(false),modal=ref(''),register=ref(false),advisorQuestion=ref(''),advisorAnswer=ref(''),adminOverview=ref(null),adminRequests=ref([]),adminUsers=ref([])
const form=ref({email:'',password:'',nickname:'',join_key:'',host_name:'我的学习设备',title:'',body:'',avatar_url:'',oj_provider:'',oj_api_key:'',advisor_provider:'',advisor_api_key:'',advisor_endpoint:'',current_password:'',new_password:'',group_name:'',group_description:'',group_visibility:'PUBLIC'})
const catalog=ref([]),comments=ref({}),replyDrafts=ref({}),advisorConsent=ref(false),advisorSources=ref([]),advisorHistory=ref([])
let groupEpoch=0
const online=computed(()=>members.value.filter(m=>m.online).length)
async function run(fn){error.value='';busy.value=true;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function openAccountPage(page){if(page==='settings')populateSettings();tab.value=page;location.hash='/'+page}
async function openReply(id){await run(async()=>{const epoch=groupEpoch;await refresh();if(epoch!==groupEpoch)return;const rows=await request('group','/group/discussions/'+id+'/comments');if(epoch!==groupEpoch)return;comments.value[id]=rows;tab.value='discussion';await nextTick();document.getElementById('discussion-'+id)?.scrollIntoView({behavior:'smooth',block:'center'})})}
watch(tab,page=>{if(['settings','notifications'].includes(page)){history.replaceState(null,'',location.pathname+location.search+'#/'+page)}else if(['/settings','/notifications'].includes(location.hash.slice(1))){history.replaceState(null,'',location.pathname+location.search)}})
function accountRoute(){const page=location.hash.slice(2);if(user.value&&['settings','notifications'].includes(page)){if(page==='settings')populateSettings();tab.value=page}}
async function loadNoticeCount(){const id=user.value?.id;if(!id)return;try{const data=await request('identity','/notifications/unread-count');if(user.value?.id===id)unreadCount.value=data.count}catch{}}
async function authenticate(){await run(async()=>{if(register.value)await request('identity','/auth/register','POST',form.value);const data=await request('identity','/auth/login','POST',form.value);setToken(data.access_token);user.value=data.user;populateSettings();await loadNoticeCount();form.value.password='';modal.value='';accountRoute();if(group.value){await restoreGroup();enter()}})}
async function restoreGroup(){try{await request('group','/group/heartbeat','POST');joined.value=true;await refresh()}catch{joined.value=false;members.value=[];discussions.value=[]}}
async function join(){await run(async()=>{await request('group','/group/join','POST',{join_key:form.value.join_key,host_name:form.value.host_name,nickname:user.value.nickname});joined.value=true;form.value.join_key='';modal.value='';tab.value='discussion';await refresh()})}
async function refresh(){if(!joined.value)return;const epoch=groupEpoch;await request('group','/group/heartbeat','POST');if(epoch!==groupEpoch)return;const [m,d]=await Promise.all([request('group','/group/members'),request('group','/group/discussions')]);if(epoch!==groupEpoch)return;members.value=m;discussions.value=d;const loaded=Object.keys(comments.value).filter(id=>d.some(post=>post.id===id));const updated=await Promise.all(loaded.map(async id=>[id,await request('group','/group/discussions/'+id+'/comments')]));if(epoch===groupEpoch)for(const [id,rows] of updated)comments.value[id]=rows}
async function loadComments(post){await run(async()=>{const epoch=groupEpoch;const rows=await request('group','/group/discussions/'+post+'/comments');if(epoch===groupEpoch)comments.value[post]=rows})}
async function reply(post){await run(async()=>{const epoch=groupEpoch;await request('group','/group/discussions/'+post+'/comments','POST',{body:replyDrafts.value[post]});const rows=await request('group','/group/discussions/'+post+'/comments');if(epoch===groupEpoch){comments.value[post]=rows;replyDrafts.value[post]=''}})}
async function publish(){await run(async()=>{await request('group','/group/discussions','POST',{title:form.value.title,body:form.value.body});form.value.title='';form.value.body='';modal.value='';await refresh()})}
function populateSettings(){if(!user.value)return;form.value.nickname=user.value.nickname;form.value.avatar_url=user.value.avatar_url||'';form.value.oj_provider=user.value.integrations?.oj_provider||'';form.value.advisor_provider=user.value.integrations?.advisor_provider||'';form.value.advisor_endpoint=user.value.integrations?.advisor_endpoint||'';form.value.oj_api_key='';form.value.advisor_api_key=''}
async function openAdvisor(){tab.value='advisor';await run(async()=>{const epoch=groupEpoch;const history=await request('identity','/advisor/history?group_id='+encodeURIComponent(group.value.id));if(epoch===groupEpoch)advisorHistory.value=history.slice().reverse()})}
async function clearAdvisor(){await run(async()=>{await request('identity','/advisor/history?group_id='+encodeURIComponent(group.value.id),'DELETE');advisorHistory.value=[];advisorAnswer.value='';advisorSources.value=[]})}
async function saveProfile(){await run(async()=>{user.value=await request('identity','/users/me','PATCH',{nickname:form.value.nickname,avatar_url:form.value.avatar_url});modal.value=''})}
async function saveIntegrations(){await run(async()=>{user.value=await request('identity','/users/me/integrations','PUT',{oj_provider:form.value.oj_provider,oj_api_key:form.value.oj_api_key,advisor_provider:form.value.advisor_provider,advisor_api_key:form.value.advisor_api_key,advisor_endpoint:form.value.advisor_endpoint});populateSettings();modal.value=''})}
async function savePassword(){await run(async()=>{await request('identity','/users/me/password','POST',{current_password:form.value.current_password,new_password:form.value.new_password});form.value.current_password='';form.value.new_password='';modal.value=''})}
async function askAdvisor(){await run(async()=>{if(!joined.value)throw new Error('请先加入群组');if(!advisorConsent.value)throw new Error('请确认发送当前群组上下文');const epoch=groupEpoch;const question=advisorQuestion.value.trim();if(!question)throw new Error('请输入问题');const data=await request('identity','/advisor/messages','POST',{group_id:group.value.id,question:question,consent:'share-group-context'});if(epoch===groupEpoch){advisorAnswer.value=data.answer;advisorSources.value=data.sources;advisorHistory.value.push({QUESTION:question,ANSWER:data.answer});if(advisorQuestion.value.trim()===question)advisorQuestion.value=''}})}
async function reloadCatalog(){await run(async()=>{catalog.value=await request('identity','/community/groups')})}
async function createGroup(){await run(async()=>{await request('identity','/community/group-requests','POST',{name:form.value.group_name,description:form.value.group_description,visibility:form.value.group_visibility});form.value.group_name='';form.value.group_description='';form.value.group_visibility='PUBLIC';modal.value='';error.value='群组创建申请已提交，等待服务部署。';await loadAdmin()})}
async function openAdmin(){tab.value='admin';await run(loadAdmin)}
async function loadAdmin(){if(user.value?.role!=='ADMIN')return;adminOverview.value=await request('identity','/admin/overview');adminRequests.value=await request('identity','/admin/group-requests');adminUsers.value=await request('identity','/admin/users');await mailPanel.value?.load()}
async function decideGroupRequest(id,status){await run(async()=>{await request('identity','/admin/group-requests/'+id,'PATCH',{status});await loadAdmin()})}
function enter(){if(!user.value){modal.value='auth';return}if(!joined.value){modal.value='join';return}tab.value='group-home';run(refresh)}
async function chooseGroup(entry){await run(async()=>{groupEpoch++;advisorAnswer.value='';advisorSources.value=[];advisorHistory.value=[];advisorQuestion.value='';advisorConsent.value=false;comments.value={};replyDrafts.value={};joined.value=false;members.value=[];discussions.value=[];group.value=null;selectGroup(entry);const info=await request('group','/group');if(info.id!==entry.id)throw new Error('群组目录与服务身份不匹配');group.value=info;if(user.value)await restoreGroup();sessionStorage.setItem('selected-group',entry.id);enter()})}
function logout(){groupEpoch++;advisorHistory.value=[];advisorSources.value=[];advisorAnswer.value='';advisorQuestion.value='';advisorConsent.value=false;comments.value={};replyDrafts.value={};form.value.advisor_api_key='';form.value.oj_api_key='';setToken('');sessionStorage.removeItem('selected-group');user.value=null;unreadCount.value=0;joined.value=false;members.value=[];discussions.value=[];group.value=null;tab.value='groups';history.replaceState(null,'',location.pathname+location.search)}
let interval
onMounted(async()=>{window.addEventListener('hashchange',accountRoute);await run(async()=>{catalog.value=await request('identity','/community/groups');try{user.value=await request('identity','/users/me');populateSettings();await loadNoticeCount()}catch{setToken('')}const last=catalog.value.find(e=>e.id===sessionStorage.getItem('selected-group'));if(last&&user.value){selectGroup(last);const info=await request('group','/group');if(info.id!==last.id)throw new Error('群组服务身份不匹配');group.value=info;await restoreGroup()}});accountRoute();interval=setInterval(()=>{if(!document.hidden)loadNoticeCount();if(!document.hidden&&joined.value&&!busy.value)run(refresh)},30000)})
onUnmounted(()=>{clearInterval(interval);window.removeEventListener('hashchange',accountRoute)})
</script>
<template>
 <aside><a class="brand">◈ 算法同行<small>ALGO TOGETHER</small></a><p class="label">学习空间</p><button :class="{active:tab==='groups'}" @click="tab='groups';reloadCatalog()">◇ 群组入口</button><template v-if="joined"><p class="label compact">当前群组</p><button :class="{active:tab==='group-home'}" @click="tab='group-home'">⌂ 群组首页</button><button :class="{active:tab==='discussion'}" @click="tab='discussion'">☷ 讨论与复盘</button><button :class="{active:tab==='advisor'}" @click="openAdvisor">✦ 机器人顾问</button><button :class="{active:tab==='members'}" @click="tab='members'">◎ 联网成员</button><button :class="{active:tab==='nodes'}" @click="tab='nodes'">⌘ 同步节点</button></template><button v-if="user?.role=== 'ADMIN'" :class="{active:tab=== 'admin'}" @click="openAdmin">管理后台</button><div class="aside-note">Spring Boot + Vue 3<small>独立群组服务 · 第二阶段</small></div></aside>
 <main><header><span>社区 / {{ {groups:'群组入口',discussion:'讨论与复盘',advisor:'机器人顾问',members:'联网成员',nodes:'同步节点',settings:'个人设置',notifications:'消息与申请',admin:'管理后台'}[tab] }}</span><AccountShortcuts :user="user" :group="group" :joined="joined" :unread="unreadCount" @page="openAccountPage" @reply="openReply" @logout="logout" @login="modal='auth'" @changed="loadNoticeCount" /></header>
 <div class="hero"><small>LEARN · SHARE · GROW</small><h1>{{tab==='groups'?'找到你的算法同伴':tab==='group-home'?(group?.name||'群组首页'):tab==='discussion'?'把思考分享给同伴':tab==='advisor'?'和你的算法顾问一起学习':tab==='nodes'?'管理你的同步设备':tab==='settings'?'管理个人资料与连接':'同伴就在这里'}}</h1><p>让每一个独立学习的时刻，都有同伴同行。</p></div>
 <p v-if="error" class="error" role="alert">{{error}}</p>
 <div v-if="joined" class="status">当前群组：{{group?.name}} <span>{{online}} 人在线</span><button class="secondary" :disabled="busy" @click="run(refresh)">同步成员</button></div>
 <section v-if="tab==='groups'"><div class="section-head"><h2>可连接的群组</h2><button :disabled="busy" @click="user?modal='create-group':modal='auth'">＋ 创建群组</button></div><div class="group-grid"><article v-for="entry in catalog" :key="entry.id" class="card"><div class="icon">⌘</div><h3>{{entry.name}}</h3><p>{{entry.description}}</p><div class="bottom"><span class="badge">{{joined&&group?.id===entry.id?'已连接':'独立群组服务'}}</span><button :disabled="busy" @click="chooseGroup(entry)">{{joined&&group?.id===entry.id?'进入群组 →':'连接群组 →'}}</button></div></article></div><div v-if="!catalog.length" class="empty">尚未加载群组目录，请检查身份服务是否启动。</div><p class="note">申请经管理员批准后，你可以在“消息与申请”中一键部署本机群组；部署成功后重新打开群组入口即可连接。</p></section>
 <section v-if="tab==='group-home'" class="group-home"><div class="section-head"><h2>{{group?.name}}</h2><button @click="tab='discussion'">进入讨论 →</button></div><p class="note">这是当前群组的独立学习空间。讨论、成员、同步节点和机器人顾问都只属于当前群组。</p><div class="settings-grid"><article class="card"><h3>群组概览</h3><p>{{group?.description||'独立群组服务'}}</p><span class="badge">{{group?.visibility==='PRIVATE'?'私密群组':'公开群组'}}</span></article><article class="card"><h3>当前活跃</h3><p><strong>{{online}}</strong> 人在线</p><p><strong>{{discussions.length}}</strong> 条讨论</p><p><strong>{{members.length}}</strong> 位成员</p></article></div><div class="section-head"><h3>群组功能</h3></div><div class="group-grid"><article class="card"><h3>讨论与复盘</h3><p>发布算法问题、经验和解题复盘。</p><button @click="tab='discussion'">打开讨论</button></article><article class="card"><h3>机器人顾问</h3><p>基于当前群组上下文获得学习建议。</p><button @click="openAdvisor">打开顾问</button></article><article class="card"><h3>联网成员</h3><p>查看本群组成员的在线状态。</p><button @click="tab='members'">查看成员</button></article></div></section>
 <section v-if="tab==='discussion'"><div class="section-head"><h2>交流与复盘</h2><button v-if="joined" @click="modal='post'">＋ 发布讨论</button></div><div v-if="!joined" class="empty">先从群组入口加入一个群组。</div><div v-else-if="!discussions.length" class="empty">分享一个算法疑问，开始第一场讨论。</div><article v-for="post in discussions" :key="post.id" class="card post" :id="'discussion-'+post.id"><span class="muted">{{post.nickname}} · {{new Date(post.created_at).toLocaleString('zh-CN')}}</span><h3>{{post.title}}</h3><p>{{post.body}}</p><button class="secondary" :disabled="busy" @click="loadComments(post.id)">查看 / 刷新回复</button><div v-for="comment in comments[post.id]||[]" :key="comment.id" class="member"><div><strong>{{comment.nickname}}</strong><small>{{new Date(comment.created_at).toLocaleString('zh-CN')}}</small><p>{{comment.body}}</p></div></div><form @submit.prevent="reply(post.id)"><label>回复同伴<textarea v-model="replyDrafts[post.id]" maxlength="5000" required></textarea></label><button :disabled="busy">发送回复</button></form></article></section>
 <section v-if="tab==='members'"><h2>联网成员</h2><div v-if="!joined" class="empty">加入群组后查看同伴。</div><div v-for="member in members" :key="member.user_id" class="member"><span class="avatar">{{member.nickname.slice(0,1)}}</span><div><strong>{{member.nickname}}</strong><small>{{member.host_name}}</small></div><span :class="['presence',{offline:!member.online}]">{{member.online?'● 在线':'● 离线'}}</span></div><p class="note">30 秒心跳同步，90 秒未收到心跳后显示离线。</p></section>
 <section v-if="tab==='advisor'" class="card advisor"><h2>群组机器人顾问</h2><p>顾问根据当前群组最近的讨论和你的会话提供算法学习建议。</p><button class="secondary" :disabled="busy" @click="clearAdvisor">清空我的当前群组会话</button><div v-for="(turn,i) in advisorHistory" :key="i" class="advisor-answer"><strong>我：{{turn.QUESTION}}</strong><p>{{turn.ANSWER}}</p></div><textarea v-model="advisorQuestion" placeholder="例如：帮我分析这道题的复杂度"></textarea><label class="consent"><input type="checkbox" v-model="advisorConsent"><span>允许将问题、我的最近会话和当前群组最近 10 条讨论发送给已配置模型服务</span></label><button :disabled="busy||!joined||!advisorConsent" @click="askAdvisor">{{busy?'处理中…':'询问顾问'}}</button><details v-if="advisorSources.length" class="advisor-sources"><summary>本次参考讨论（{{advisorSources.length}}）</summary><p v-for="source in advisorSources" :key="source.id">{{source.title}}</p></details><p class="note">{{user?.integrations?.advisor_key_configured?'已保存模型配置。会话仅自己可见，可随时清空。':'请在个人设置中填写模型接口地址、模型名称和 API 密钥。'}}</p></section>
 <section v-if="tab==='settings'"><h2>个人设置</h2><div class="settings-grid"><article class="card"><h3>资料与头像</h3><label>昵称<input v-model="form.nickname"></label><label>头像地址<input v-model="form.avatar_url" placeholder="https://... 或本地图片地址"></label><button @click="saveProfile">保存资料</button></article><article class="card"><h3>修改密码</h3><label>当前密码<input v-model="form.current_password" type="password"></label><label>新密码<input v-model="form.new_password" type="password" minlength="8"></label><button @click="savePassword">更新密码</button></article><article class="card"><h3>服务连接</h3><label>OJ 平台<select v-model="form.oj_provider"><option value="">未配置</option><option>Codeforces</option><option>AtCoder</option><option>Luogu</option></select></label><label>OJ API 密钥<input v-model="form.oj_api_key" type="password"></label><label>模型接口地址<input v-model="form.advisor_endpoint" type="url" placeholder="https://服务地址/v1/chat/completions"></label><label>顾问模型名称<input v-model="form.advisor_provider" placeholder="填写服务支持的模型名称"></label><label>顾问 API 密钥（留空保留已保存密钥）<input v-model="form.advisor_api_key" type="password"></label><button @click="saveIntegrations">保存连接设置</button></article></div></section>
 <NotificationPanel v-if="tab==='notifications'&&user" :key="user.id" @changed="loadNoticeCount" />
 <NodePanel v-if="tab==='nodes'" :key="group?.id||'none'" :joined="joined" />
 <section v-if="tab==='admin'"><div class="section-head"><h2>管理后台</h2><button :disabled="busy" @click="run(loadAdmin)">刷新</button></div><div class="admin-grid"><article class="card">用户 {{adminOverview?.users??'—'}}</article><article class="card">管理员 {{adminOverview?.admins??'—'}}</article><article class="card">群组 {{adminOverview?.configured_groups??'—'}}</article><article class="card">待处理 {{adminOverview?.pending_group_requests??'—'}}</article></div><PublicAccessPanel /><MailJobsPanel ref="mailPanel" /><h3>群组创建申请</h3><div v-if="!adminRequests.length" class="empty">暂无申请</div><div v-for="item in adminRequests" :key="item.ID" class="member"><div><strong>{{item.NAME}}</strong><small>{{item.DESCRIPTION}}</small></div><span class="badge">{{item.STATUS}}</span><template v-if="item.STATUS==='PENDING'"><button :disabled="busy" @click="decideGroupRequest(item.ID,'APPROVED')">批准</button><button class="secondary" :disabled="busy" @click="decideGroupRequest(item.ID,'REJECTED')">驳回</button></template></div><h3>账号列表</h3><div v-for="item in adminUsers" :key="item.ID" class="member"><div><strong>{{item.NICKNAME}}</strong><small>{{item.EMAIL}}</small></div><span class="badge">{{item.ROLE}}</span></div></section><footer>算法同行 · 目标驱动的算法学习社区</footer></main>
 <div v-if="modal" class="overlay"><div class="dialog" role="dialog" aria-modal="true"><div class="section-head"><h2>{{modal==='auth'?(register?'创建学习账号':'欢迎回来'):modal==='join'?'密钥加入群组':modal==='post'?'发布讨论':'申请创建群组'}}</h2><button class="secondary" @click="modal=''">✕</button></div><form @submit.prevent="modal==='auth'?authenticate():modal==='join'?join():modal==='post'?publish():createGroup()"><template v-if="modal==='auth'"><label>邮箱<input v-model="form.email" type="email" required></label><label>密码<input v-model="form.password" type="password" minlength="8" required></label><label v-if="register">昵称<input v-model="form.nickname" maxlength="40" required></label><button type="button" class="secondary" @click="register=!register">{{register?'已有账号？登录':'还没有账号？注册'}}</button></template><template v-if="modal==='join'"><label v-if="group?.visibility!=='PUBLIC'">群主分享的联网密钥<input v-model="form.join_key" type="password" minlength="16" required></label><label>设备名称<input v-model="form.host_name" maxlength="80" required></label></template><template v-if="modal==='post'"><label>标题<input v-model="form.title" maxlength="100" required></label><label>内容<textarea v-model="form.body" maxlength="20000" required></textarea></label></template><template v-if="modal==='create-group'"><label>群组名称<input v-model="form.group_name" maxlength="60" required></label><label>群组简介<textarea v-model="form.group_description" maxlength="500" required></textarea></label><label>群组类型<select v-model="form.group_visibility"><option value="PUBLIC">公开群组 · 无需加入密钥</option><option value="PRIVATE">私密群组 · 需要加入密钥</option></select></label><p class="note">公开群组部署后可直接进入；私密群组部署后需要管理员生成加入密钥，并通过应用内消息发送给申请人。</p></template><p v-if="error" class="error">{{error}}</p><button class="submit" :disabled="busy">{{busy?'处理中…':'确认'}}</button></form></div></div>
</template>



